Next.js Subscription Lifecycle
Volume 07 - Advanced Application Architecture

Client hook
export function useWorkspaceTaskRealtime(
workspaceId: string,
) {
const queryClient = useQueryClient()
const supabase = useMemo(
() => createBrowserSupabaseClient(),
[],
)

useEffect(() => {
let channel: RealtimeChannel | undefined
let disposed = false

const connect = async () => {
await supabase.realtime.setAuth()
if (disposed) return

channel = supabase
.channel(`workspace:${workspaceId}:tasks`, {
config: { private: true },
})
.on('broadcast', { event: 'INSERT' }, refresh)
.on('broadcast', { event: 'UPDATE' }, refresh)
.on('broadcast', { event: 'DELETE' }, refresh)
.subscribe((status, error) => {
if (status === 'SUBSCRIBED') refresh()
if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
console.error('Realtime channel failure', error)
}
})
}

const refresh = () => {
void queryClient.invalidateQueries({
queryKey: taskKeys.all,
})
}

void connect()

return () => {
disposed = true
if (channel) void supabase.removeChannel(channel)
}
}, [queryClient, supabase, workspaceId])
}

Why cleanup matters
• Route/workspace changes can otherwise leave unused subscriptions alive.

• Unused channels consume Realtime resources and make duplicate handlers more likely.

• Supabase exposes removeChannel() specifically to tear down a channel.

Reconnect recovery
On a successful subscription/re-subscription, TaskFlow invalidates Task queries. This closes the
“missed events while disconnected” gap by asking the HTTP API for current truth.

Token refresh
Realtime Authorization uses the authenticated JWT. Supabase Realtime supports in-band
access-token updates; the browser Supabase client is the source of the session, and setAuth()

establishes the token used for the private channel.

